// Normalize freelance project lead
const body = $json.body || {};
const clientName = body.client_name || body.name || 'Enterprise Client';
const email = body.email || 'client@example.com';
const projectTitle = body.project_title || body.title || 'Custom Software Solution';
const budget = body.budget || 'Flexible / To be estimated';
const timeline = body.timeline || '1-2 Months';
const requirements = body.requirements || body.description || body.brief || JSON.stringify(body);

return [{
  json: {
    client_name: clientName,
    client_email: email,
    project_title: projectTitle,
    client_budget: budget,
    client_timeline: timeline,
    brief_text: requirements,
    received_at: $now.toFormat('dd LLL yyyy, HH:mm')
  }
}];

